var assert = require('assert');
var ms = require('./');

describe('proof', function () {
  it('fails on the patched build', function () {
    // Test that parsing '1y' gives approximately one year in milliseconds
    // Original: y = d * 365.25 → 1 year = 365.25 days
    // Patched: y = d / 365.25 → 1 year = 1/365.25 days ≈ 24 minutes
    const originalYearMs = 365.25 * 24 * 60 * 60 * 1000; // ~31.5576e9 ms
    const patchedYearMs = (24 * 60 * 60 * 1000) / 365.25; // ~1.997e6 ms ≈ 24 minutes

    // The patched version should not return a value close to a year
    const result = ms('1y');
    assert.notEqual(result, originalYearMs, 'should not be a year');
    assert.ok(result < 1000 * 60 * 60, 'should be less than 1 hour'); // 24 minutes is ~1.44e6 ms
  });
});

