var assert = require('assert');
var ms = require('./');

describe('proof', function () {
  it('fails on the patched build', function () {
    // The original behavior: 1 year = 365.25 days → correct
    // The patched behavior: 1 year = 1/365.25 days → wrong
    // So the original should parse '1y' to ~31.5576e9 ms
    // The patched version will parse it to ~1.997e6 ms (about 24 minutes)

    const expected = 365.25 * 24 * 60 * 60 * 1000; // ~31.5576e9 ms
    const result = ms('1y');

    // The original should give the correct year value
    // The patched version should NOT
    assert.notEqual(result, expected, 'patched version should not give a full year');
    assert.ok(result < 1000 * 60 * 60, 'patched result is too large if it were a year');
  });
});

